export const getAdminUpdateProductUrl = (id: number,) => {




  return `/api/admin/products/${id}`
}

/**
 * @summary Admin update product (approve, remove)
 */
export const adminUpdateProduct = async (id: number,
    adminProductUpdate: AdminProductUpdate, options?: RequestInit): Promise<Product> => {

  return customFetch<Product>(getAdminUpdateProductUrl(id),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      adminProductUpdate,)
  }
);}




